export { default as NodeCanvas } from './NodeCanvas.vue';
export { default as NodeCanvasBars } from './NodeCanvasBars.vue';
export { default as NodeCanvasCard } from './NodeCanvasCard.vue';
export { default as NodeCanvasChecklist } from './NodeCanvasChecklist.vue';
export { default as NodeCanvasNote } from './NodeCanvasNote.vue';
export { default as NodeCanvasSource } from './NodeCanvasSource.vue';
export type {
  NodeCanvasAnchor,
  NodeCanvasBarSegment,
  NodeCanvasBarsProps,
  NodeCanvasCardProps,
  NodeCanvasChecklistProps,
  NodeCanvasChecklistRow,
  NodeCanvasCursor,
  NodeCanvasEdge,
  NodeCanvasEdgeVariant,
  NodeCanvasNode,
  NodeCanvasNodeSlotProps,
  NodeCanvasNoteProps,
  NodeCanvasPoint,
  NodeCanvasProps,
  NodeCanvasSide,
  NodeCanvasSourceProps,
} from './types';

import type {
  NodeCanvasAnchor,
  NodeCanvasPoint,
  NodeCanvasRect,
  NodeCanvasSide,
} from './types';

const NORMALS: Record<NodeCanvasSide, NodeCanvasPoint> = {
  left: { x: -1, y: 0 },
  right: { x: 1, y: 0 },
  top: { x: 0, y: -1 },
  bottom: { x: 0, y: 1 },
};

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

export function anchorPoint(
  rect: NodeCanvasRect,
  anchor: NodeCanvasAnchor,
): NodeCanvasPoint {
  const t = clamp(anchor.offset ?? 0.5, 0, 1);
  switch (anchor.side) {
    case 'left':
      return { x: rect.x, y: rect.y + rect.height * t };
    case 'right':
      return { x: rect.x + rect.width, y: rect.y + rect.height * t };
    case 'top':
      return { x: rect.x + rect.width * t, y: rect.y };
    default:
      return { x: rect.x + rect.width * t, y: rect.y + rect.height };
  }
}

/** Cubic bezier that leaves and enters each node along its side normal. */
export function bezierPath(
  start: NodeCanvasPoint,
  startSide: NodeCanvasSide,
  end: NodeCanvasPoint,
  endSide: NodeCanvasSide,
): string {
  const distance = Math.hypot(end.x - start.x, end.y - start.y);
  // Same-side edges loop around, so they need a shorter reach to stay compact.
  const reach = Math.max(48, distance * (startSide === endSide ? 0.25 : 0.45));
  const a = NORMALS[startSide];
  const b = NORMALS[endSide];
  const c1 = { x: start.x + a.x * reach, y: start.y + a.y * reach };
  const c2 = { x: end.x + b.x * reach, y: end.y + b.y * reach };
  return `M ${start.x} ${start.y} C ${c1.x} ${c1.y}, ${c2.x} ${c2.y}, ${end.x} ${end.y}`;
}

export function unionRect(rects: NodeCanvasRect[]): NodeCanvasRect {
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const r of rects) {
    minX = Math.min(minX, r.x);
    minY = Math.min(minY, r.y);
    maxX = Math.max(maxX, r.x + r.width);
    maxY = Math.max(maxY, r.y + r.height);
  }
  if (!Number.isFinite(minX)) return { x: 0, y: 0, width: 1, height: 1 };
  return { x: minX, y: minY, width: maxX - minX, height: maxY - minY };
}

/** Point on a looping polyline at progress `t` (0–1). */
export function pointOnLoop(
  points: NodeCanvasPoint[],
  t: number,
): NodeCanvasPoint {
  const first = points[0];
  if (!first) return { x: 0, y: 0 };
  if (points.length === 1) return first;
  const scaled = (((t % 1) + 1) % 1) * points.length;
  const index = Math.floor(scaled);
  const from = points[index] ?? first;
  const to = points[(index + 1) % points.length] ?? first;
  // Smoothstep easing so the cursor slows at each waypoint, like a hand would.
  const f = scaled - index;
  const e = f * f * (3 - 2 * f);
  return { x: from.x + (to.x - from.x) * e, y: from.y + (to.y - from.y) * e };
}

export interface NodeCanvasPoint {
  x: number;
  y: number;
}

export type NodeCanvasSide = 'left' | 'right' | 'top' | 'bottom';

export interface NodeCanvasAnchor {
  side: NodeCanvasSide;
  /** Position along the side, from 0 (start) to 1 (end). Defaults to `0.5`. */
  offset?: number;
}

export interface NodeCanvasNode {
  /** Unique id. Also names the `#node-<id>` slot. */
  id: string;
  /** Accessible name of the node. */
  label: string;
  /** Left edge in canvas units. */
  x: number;
  /** Top edge in canvas units. */
  y: number;
  width: number;
  height: number;
  /** Tilt in degrees, e.g. `3` for a sticky note. */
  rotate?: number;
  /** Corner radius in canvas units, used by the selection outline. Defaults to `24`. */
  radius?: number;
  /** Fill of the node in the minimap. Defaults to a neutral grey. */
  minimapColor?: string;
  /** Set `false` to keep the node from being dragged or selected. */
  interactive?: boolean;
}

export type NodeCanvasEdgeVariant = 'solid' | 'dashed';

export interface NodeCanvasEdge {
  id: string;
  /** Source node id. */
  from: string;
  /** Target node id. */
  to: string;
  fromAnchor?: NodeCanvasAnchor;
  toAnchor?: NodeCanvasAnchor;
  /** `solid` draws an accent line, `dashed` a muted dashed line. */
  variant?: NodeCanvasEdgeVariant;
  /** Draws an arrowhead at the target end. */
  arrow?: boolean;
}

export interface NodeCanvasCursor {
  id: string;
  /** Collaborator name shown in the label. */
  name: string;
  /** Arrow and label color, e.g. `#34d07f`. */
  color: string;
  /** Waypoints in canvas units. The cursor loops through them. */
  path: NodeCanvasPoint[];
  /** Duration of one loop in milliseconds. Defaults to `9000`. */
  duration?: number;
}

export interface NodeCanvasProps {
  nodes: NodeCanvasNode[];
  edges?: NodeCanvasEdge[];
  /** Live collaborator cursors. They stay still when reduced motion is on. */
  cursors?: NodeCanvasCursor[];
  /** Breadcrumb in the header, e.g. `['Plant North', 'Line 3 Health']`. */
  breadcrumb?: string[];
  /** Grid cell size in canvas units. */
  gridSize?: number;
  minZoom?: number;
  maxZoom?: number;
  /** Amount each zoom button press changes the zoom. */
  zoomStep?: number;
  /** Shows the minimap in the top-right corner. */
  minimap?: boolean;
  /** Accessible name of the canvas region. */
  ariaLabel?: string;
  class?: string;
}

export interface NodeCanvasNodeSlotProps {
  node: NodeCanvasNode;
  selected: boolean;
}

export interface NodeCanvasRect {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface NodeCanvasMinimapItem extends NodeCanvasRect {
  id: string;
  color: string;
}

export interface NodeCanvasEdgePath {
  id: string;
  d: string;
  variant: NodeCanvasEdgeVariant;
  arrow: boolean;
  end: NodeCanvasPoint;
  start: NodeCanvasPoint;
}

export interface NodeCanvasFrameProps {
  node: NodeCanvasNode;
  /** Current position, which may differ from `node.x`/`node.y` after a drag. */
  position: NodeCanvasPoint;
  selected: boolean;
  zoom: number;
}

export interface NodeCanvasEdgesProps {
  paths: NodeCanvasEdgePath[];
}

export interface NodeCanvasMinimapProps {
  items: NodeCanvasMinimapItem[];
  viewport: NodeCanvasRect;
}

export interface NodeCanvasZoomProps {
  zoom: number;
  minZoom: number;
  maxZoom: number;
}

export interface NodeCanvasCursorProps {
  cursor: NodeCanvasCursor;
  /** Freezes the cursor on its first waypoint. */
  still: boolean;
}

export interface NodeCanvasSourceProps {
  label: string;
  /** Lucide icon name. Defaults to `lucide:box`. */
  icon?: string;
  class?: string;
}

export interface NodeCanvasNoteProps {
  text: string;
  class?: string;
}

export interface NodeCanvasCardProps {
  title: string;
  /** Optional Lucide icon before the title. */
  icon?: string;
  /** Tailwind text color class for the icon. */
  iconClass?: string;
  class?: string;
}

export interface NodeCanvasBarSegment {
  value: number;
  /** CSS color of the segment. */
  color: string;
}

export interface NodeCanvasBarsProps {
  /** One entry per bar; each bar stacks its segments bottom to top. */
  bars: NodeCanvasBarSegment[][];
  /** Accessible summary of the chart. */
  label: string;
  class?: string;
}

export interface NodeCanvasChecklistRow {
  id: string;
  label: string;
  value: number;
  checked?: boolean;
}

export type NodeCanvasSortDirection = 'desc' | 'asc';

export interface NodeCanvasChecklistProps {
  rows: NodeCanvasChecklistRow[];
  /** First column heading. */
  labelHeader?: string;
  /** Chip next to the first heading, e.g. `Shift`. Hidden when empty. */
  chip?: string;
  /** Value column heading. */
  valueHeader?: string;
  class?: string;
}
